/* Fotos de Iraia integradas: si la imagen alojada no carga, se usa la copia incrustada */
(function(){var F={"hero":"data:image/jpeg;base64,","retrato":"data:image/jpeg;base64,","barra":"data:image/jpeg;base64,","sesion":"data:image/jpeg;base64,"};
function poner(img){var k=img.getAttribute("data-foto");if(k&&F[k]&&img.src!==F[k]){img.src=F[k];}}
document.querySelectorAll("img[data-foto]").forEach(function(img){img.addEventListener("error",function(){poner(img);});if(img.complete&&img.naturalWidth===0){poner(img);}});
setTimeout(function(){document.querySelectorAll("img[data-foto]").forEach(function(img){if(!img.naturalWidth)poner(img);});},2500);
})();
